use std::fs

fn all_digits(s: string) -> bool {
    if s.len() == 0 {
        return false
    }
    for c in s.chars() {
        if c < '0' || c > '9' {
            return false
        }
    }
    true
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut users: Vec<string> = []
    let mut counts: Vec<int> = []
    let mut totals: Vec<int> = []
    let mut akey_u: Vec<string> = []
    let mut akey_a: Vec<string> = []
    let mut acnt: Vec<int> = []
    let mut bad = 0
    for line in text.lines() {
        let parts: Vec<string> = line.split(" ").map(|p| p.to_string()).collect()
        if parts.len() != 3 || !all_digits(parts[2]) {
            bad += 1
            continue
        }
        let u = parts[0]
        let act = parts[1]
        let secs: int = parts[2].parse::<int>().unwrap_or(0)
        let mut ui: int = -1
        let mut k = 0
        while k < users.len() as int {
            if users[k] == u {
                ui = k
            }
            k += 1
        }
        if ui < 0 {
            users.push(u)
            counts.push(0)
            totals.push(0)
            ui = users.len() as int - 1
        }
        counts[ui] = counts[ui] + 1
        totals[ui] = totals[ui] + secs
        let mut ai: int = -1
        let mut m = 0
        while m < acnt.len() as int {
            if akey_u[m] == u && akey_a[m] == act {
                ai = m
            }
            m += 1
        }
        if ai < 0 {
            akey_u.push(u)
            akey_a.push(act)
            acnt.push(0)
            ai = acnt.len() as int - 1
        }
        acnt[ai] = acnt[ai] + 1
    }
    let n: int = users.len() as int
    let mut order: Vec<int> = []
    let mut x = 0
    while x < n {
        order.push(x)
        x += 1
    }
    let mut i = 1
    while i < n {
        let mut j = i
        while j > 0 {
            let a = order[j - 1]
            let b = order[j]
            if totals[b] > totals[a] || (totals[b] == totals[a] && users[b] < users[a]) {
                order[j - 1] = b
                order[j] = a
                j -= 1
            } else {
                break
            }
        }
        i += 1
    }
    for idx in order {
        let u = users[idx]
        let mut bc = 0
        let mut ba = ""
        let mut m = 0
        while m < acnt.len() as int {
            if akey_u[m] == u {
                if acnt[m] > bc || (acnt[m] == bc && akey_a[m] < ba) {
                    bc = acnt[m]
                    ba = akey_a[m]
                }
            }
            m += 1
        }
        println("${u} ${counts[idx]} ${totals[idx]} ${ba}")
    }
    println("malformed: ${bad}")
}

